using DotNet.Testcontainers.Builders;
using System.Text.Json;

await using var network = new NetworkBuilder().WithName("asagiri-dotnet-193-" + Guid.NewGuid().ToString("N")[..8]).Build();
await network.CreateAsync();
await using var web = new ContainerBuilder("nginx:alpine")
  .WithImagePullPolicy(_ => false)
  .WithNetwork(network).WithNetworkAliases("web")
  .WithCreateParameterModifier(p => Console.WriteLine("WEB_CREATE " + JsonSerializer.Serialize(new { p.HostConfig.NetworkMode, p.NetworkingConfig.EndpointsConfig })))
  .Build();
await using var client = new ContainerBuilder("alpine:3.22")
  .WithImagePullPolicy(_ => false)
  .WithNetwork(network)
  .WithCreateParameterModifier(p => Console.WriteLine("CLIENT_CREATE " + JsonSerializer.Serialize(new { p.HostConfig.NetworkMode, p.NetworkingConfig.EndpointsConfig })))
  .WithCommand("sleep", "100")
  .Build();
await web.StartAsync();
await client.StartAsync();
foreach (var container in new[] { web, client })
{
  var argsForInspect = new System.Diagnostics.ProcessStartInfo("docker") { RedirectStandardOutput = true };
  foreach (var arg in new[] { "inspect", "--format", "{{json .NetworkSettings.Networks}}", container.Id }) argsForInspect.ArgumentList.Add(arg);
  using var command = System.Diagnostics.Process.Start(argsForInspect);
  Console.WriteLine(command!.StandardOutput.ReadToEnd());
  await command.WaitForExitAsync();
}
var lookup = await client.ExecAsync(new[] { "sh", "-ec", "cat /etc/resolv.conf; nslookup -type=a web; wget -qO- -T 5 http://web/" });
Console.Write(lookup.Stdout);
if (lookup.ExitCode != 0 || !lookup.Stdout.Contains("nameserver 127.0.0.11") || !lookup.Stdout.Contains("Welcome to nginx"))
  throw new Exception($"DNS or HTTP failed: {lookup.ExitCode} {lookup.Stderr}");
Console.WriteLine($"NETWORK {network.Name} WEB {web.Id} CLIENT {client.Id}");
